   562→              this.writeC(`${this.indent()}${elemType} ${varName}[${len}] = ${expr};`);
   563→            } else {
   564→              this.writeC(`${this.indent()}${elemType}* ${varName} = ${expr};`);
   565→            }
   566→          } else {
   567→            const cType = this.mapVType(ta);
   568→            const expr = this.genVExpression(assignStmt.value);
   569→            this.writeC(`${this.indent()}${cType} ${varName} = ${expr};`);
   570→          }
